-- PostgreSQL 是身份、草稿和冻结载荷的唯一权威；所有资源均使用稳定 UUID。
CREATE TABLE local_user(id uuid PRIMARY KEY, username varchar(100) NOT NULL UNIQUE, display_name varchar(200) NOT NULL, password_hash text NOT NULL);
CREATE TABLE auth_session(token_hash char(64) PRIMARY KEY,user_id uuid NOT NULL REFERENCES local_user(id),expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE space(id uuid PRIMARY KEY,code varchar(80) NOT NULL UNIQUE,name varchar(200) NOT NULL,namespace_uri varchar(1000) NOT NULL UNIQUE,domain varchar(200) NOT NULL,status varchar(20) NOT NULL DEFAULT 'ACTIVE',draft_rev bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE space_member(space_id uuid NOT NULL REFERENCES space(id),user_id uuid NOT NULL REFERENCES local_user(id),role varchar(10) NOT NULL CHECK(role IN ('OWNER','EDITOR','VIEWER')),PRIMARY KEY(space_id,user_id));
CREATE TABLE ont_class(id uuid PRIMARY KEY,space_id uuid NOT NULL REFERENCES space(id),name varchar(200) NOT NULL,parent_id uuid REFERENCES ont_class(id),description text NOT NULL,deprecated boolean NOT NULL,UNIQUE(id,space_id));
CREATE UNIQUE INDEX class_sibling_name ON ont_class(space_id,COALESCE(parent_id,'00000000-0000-0000-0000-000000000000'::uuid),name);
CREATE TABLE ont_property(id uuid PRIMARY KEY,space_id uuid NOT NULL REFERENCES space(id),domain_class_id uuid NOT NULL,name varchar(200) NOT NULL,range_type varchar(10) NOT NULL CHECK(range_type IN('STRING','INTEGER','DECIMAL','BOOLEAN','DATE')),required boolean NOT NULL,description text NOT NULL,FOREIGN KEY(domain_class_id,space_id) REFERENCES ont_class(id,space_id),UNIQUE(domain_class_id,name));
CREATE TABLE operation(id uuid PRIMARY KEY,space_id uuid NOT NULL REFERENCES space(id),code varchar(80) NOT NULL,name varchar(200) NOT NULL,kind varchar(30) NOT NULL DEFAULT 'OBJECT_QUERY',query_template text NOT NULL,max_rows integer NOT NULL CHECK(max_rows BETWEEN 1 AND 500),timeout_ms integer NOT NULL CHECK(timeout_ms BETWEEN 100 AND 10000),UNIQUE(space_id,code));
CREATE TABLE candidate(id uuid PRIMARY KEY,space_id uuid NOT NULL REFERENCES space(id),draft_rev bigint NOT NULL,sha256 char(64) NOT NULL,status varchar(20) NOT NULL DEFAULT 'TESTING',payload bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE execution(id uuid PRIMARY KEY,space_id uuid NOT NULL REFERENCES space(id),trace_id uuid NOT NULL,subject_type varchar(20) NOT NULL,subject_id uuid NOT NULL REFERENCES candidate(id),op_code varchar(80) NOT NULL,status varchar(20) NOT NULL,error_code varchar(100),elapsed_ms bigint NOT NULL,candidate_sha256 char(64) NOT NULL,result_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE execution_step(id bigserial PRIMARY KEY,execution_id uuid NOT NULL REFERENCES execution(id),step_order integer NOT NULL,kind varchar(50) NOT NULL,status varchar(20) NOT NULL,detail text NOT NULL);
CREATE TABLE audit_event(id bigserial PRIMARY KEY,space_id uuid NOT NULL REFERENCES space(id),actor_id uuid NOT NULL REFERENCES local_user(id),action varchar(80) NOT NULL,draft_rev bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
-- 冻结内容和摘要不可被 UPDATE；损坏测试以禁用触发器的维护身份执行。
CREATE FUNCTION immutable_candidate() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'candidate is immutable'; END $$;
CREATE TRIGGER candidate_no_update BEFORE UPDATE ON candidate FOR EACH ROW EXECUTE FUNCTION immutable_candidate();
